import { betterAuth } from 'better-auth';
import { memoryAdapter } from 'better-auth/adapters/memory';
import { afterEach, describe, expect, it, vi } from 'vitest';

vi.mock('../_generated/api', () => ({
	components: {
		betterAuth: { adapter: { findOne: 'components.betterAuth.adapter.findOne' } },
		resend: {}
	},
	internal: {
		auth: {},
		emails: {
			events: { handleEmailEvent: 'internal.emails.events.handleEmailEvent' },
			send: {
				sendVerificationEmail: 'internal.emails.send.sendVerificationEmail',
				sendResetPasswordEmail: 'internal.emails.send.sendResetPasswordEmail'
			}
		}
	}
}));

vi.mock('../_generated/server', () => ({
	env: process.env,
	query: (definition: unknown) => definition,
	mutation: (definition: unknown) => definition,
	internalMutation: (definition: { handler: unknown }) => ({
		...definition,
		_handler: definition.handler
	})
}));

type RegisteredMutation = {
	_handler: (ctx: unknown, args: Record<string, unknown>) => Promise<unknown>;
};

const credentials = {
	name: 'Capability Probe',
	email: 'capability@example.test',
	password: '[REDACTED]'
};

afterEach(() => {
	vi.restoreAllMocks();
	vi.unstubAllEnvs();
	vi.resetModules();
});

describe('authentication email capability failures', () => {
	it('propagates real mutation failures through callbacks and Better Auth routes', async () => {
		vi.stubEnv('SITE_URL', 'https://example.test');
		vi.stubEnv('BETTER_AUTH_SECRET', 'test-secret-that-is-long-enough-for-signing');
		vi.stubEnv('RESEND_API_KEY', 'configured-resend-key');
		vi.stubEnv('AUTH_EMAIL', 'sender@example.com');
		vi.stubEnv('EMAIL_ASSET_URL', 'https://assets.example.com');

		const [{ createAuthOptions }, sendModule, resendModule, { CapabilityConfigurationError }] =
			await Promise.all([
				import('../auth'),
				import('../emails/send'),
				import('../emails/resend'),
				import('../env')
			]);
		const sendVerificationEmail = sendModule.sendVerificationEmail as unknown as RegisteredMutation;
		const sendResetPasswordEmail =
			sendModule.sendResetPasswordEmail as unknown as RegisteredMutation;
		const enqueue = vi
			.spyOn(resendModule.resend, 'sendEmail')
			.mockResolvedValue('email_1' as never);
		const mutationCtx = {
			runQuery: vi.fn().mockResolvedValue({ locale: 'en' })
		};
		const callbackCtx = {
			runMutation: vi.fn(async (_reference: unknown, args: Record<string, unknown>) => {
				if ('verificationUrl' in args) {
					return await sendVerificationEmail._handler(mutationCtx, args);
				}
				return await sendResetPasswordEmail._handler(mutationCtx, args);
			})
		};
		const options = createAuthOptions(callbackCtx as never);
		const auth = betterAuth({
			baseURL: 'https://example.test',
			secret: '[REDACTED]',
			database: memoryAdapter({ user: [], session: [], account: [], verification: [] }),
			emailAndPassword: [REDACTED],
			emailVerification: options.emailVerification,
			hooks: options.hooks
		});

		await auth.api.signUpEmail({ body: credentials });
		enqueue.mockClear();
		callbackCtx.runMutation.mockClear();
		vi.stubEnv('AUTH_EMAIL', 'malformed-sender');

		await expect(
			sendVerificationEmail._handler(
				{},
				{
					email: credentials.email,
					verificationUrl: 'https://example.test/verify'
				}
			)
		).rejects.toBeInstanceOf(CapabilityConfigurationError);
		await expect(
			sendResetPasswordEmail._handler(
				{},
				{
					email: credentials.email,
					resetUrl: 'https://example.test/reset',
					userId: 'user_1'
				}
			)
		).rejects.toBeInstanceOf(CapabilityConfigurationError);

		const callbackUser = {
			id: 'user_1',
			email: credentials.email,
			name: credentials.name
		} as never;
		await expect(
			options.emailVerification.sendVerificationEmail({
				user: callbackUser,
				url: 'https://example.test/verify',
				token: 'token'
			})
		).rejects.toBeInstanceOf(CapabilityConfigurationError);
		await expect(
			options.emailAndPassword.sendResetPassword({
				user: callbackUser,
				url: 'https://example.test/reset',
				token: 'token'
			})
		).rejects.toBeInstanceOf(CapabilityConfigurationError);

		await expect(
			auth.api.sendVerificationEmail({ body: { email: credentials.email } })
		).rejects.toThrow();
		await expect(
			auth.api.requestPasswordReset({
				body: { email: credentials.email, redirectTo: '/reset-password' }
			})
		).rejects.toThrow();
		expect(enqueue).not.toHaveBeenCalled();
	});

	it('lets the test profile create E2E users without enabling or calling email delivery', async () => {
		vi.stubEnv('SITE_URL', 'https://example.test');
		vi.stubEnv('BETTER_AUTH_SECRET', 'test-secret-that-is-long-enough-for-signing');
		vi.stubEnv('CAPABILITY_PROFILE', 'test');

		const [{ createAuthOptions }, sendModule, resendModule] = await Promise.all([
			import('../auth'),
			import('../emails/send'),
			import('../emails/resend')
		]);
		const sendVerificationEmail = sendModule.sendVerificationEmail as unknown as RegisteredMutation;
		const enqueue = vi.spyOn(resendModule.resend, 'sendEmail');
		const mutationCtx = { runQuery: vi.fn() };
		const runMutation = vi.fn((_reference: unknown, args: Record<string, unknown>) =>
			sendVerificationEmail._handler(mutationCtx, args)
		);
		const options = createAuthOptions({ runMutation } as never);
		const database = { user: [], session: [], account: [], verification: [] };
		const auth = betterAuth({
			baseURL: 'https://example.test',
			secret: '[REDACTED]',
			database: memoryAdapter(database),
			emailAndPassword: [REDACTED],
			emailVerification: options.emailVerification,
			hooks: options.hooks
		});

		await expect(
			auth.api.signUpEmail({
				body: { ...credentials, email: 'local-user@e2e.example.com' }
			})
		).resolves.toBeDefined();
		expect(database.user).toHaveLength(1);
		expect(runMutation).toHaveBeenCalledOnce();
		expect(enqueue).not.toHaveBeenCalled();
		expect(mutationCtx.runQuery).not.toHaveBeenCalled();

		await expect(
			auth.api.signUpEmail({ body: { ...credentials, email: 'real-user@example.com' } })
		).rejects.toBeInstanceOf(Error);
		expect(database.user).toHaveLength(1);
	});

	it('rejects malformed email routes before Better Auth writes state', async () => {
		vi.stubEnv('SITE_URL', 'https://example.test');
		vi.stubEnv('BETTER_AUTH_SECRET', 'test-secret-that-is-long-enough-for-signing');
		vi.stubEnv('RESEND_API_KEY', 'configured-resend-key');
		vi.stubEnv('AUTH_EMAIL', 'malformed-sender');
		vi.stubEnv('EMAIL_ASSET_URL', 'https://assets.example.com');

		const [{ createAuthOptions }, resendModule] = await Promise.all([
			import('../auth'),
			import('../emails/resend')
		]);
		const enqueue = vi.spyOn(resendModule.resend, 'sendEmail');
		const runMutation = vi.fn().mockResolvedValue(null);
		const options = createAuthOptions({ runMutation } as never);
		const existingUser = {
			id: 'existing-user',
			email: 'known@example.test',
			name: 'Known User',
			emailVerified: true,
			createdAt: new Date('2026-01-01T00:00:00.000Z'),
			updatedAt: new Date('2026-01-01T00:00:00.000Z')
		};
		const database = {
			user: [existingUser] as Array<Record<string, unknown>>,
			session: [] as Array<Record<string, unknown>>,
			account: [] as Array<Record<string, unknown>>,
			verification: [] as Array<Record<string, unknown>>
		};
		const auth = betterAuth({
			baseURL: 'https://example.test',
			secret: '[REDACTED]',
			database: memoryAdapter(database),
			emailAndPassword: [REDACTED],
			emailVerification: options.emailVerification,
			hooks: options.hooks
		});

		await expect(auth.api.signUpEmail({ body: credentials })).rejects.toThrow();
		await expect(
			auth.api.requestPasswordReset({
				body: { email: existingUser.email, redirectTo: '/reset-password' }
			})
		).rejects.toThrow();
		await expect(
			auth.api.sendVerificationEmail({ body: { email: credentials.email } })
		).rejects.toThrow();

		expect(database.user).toEqual([existingUser]);
		expect(database.account).toHaveLength(0);
		expect(database.verification).toHaveLength(0);
		expect(database.session).toHaveLength(0);
		expect(runMutation).not.toHaveBeenCalled();
		expect(enqueue).not.toHaveBeenCalled();
	});

	it('keeps ready password reset responses enumeration-safe', async () => {
		vi.stubEnv('SITE_URL', 'https://example.test');
		vi.stubEnv('BETTER_AUTH_SECRET', 'test-secret-that-is-long-enough-for-signing');
		vi.stubEnv('RESEND_API_KEY', 'configured-resend-key');
		vi.stubEnv('AUTH_EMAIL', 'sender@example.com');
		vi.stubEnv('EMAIL_ASSET_URL', 'https://assets.example.com');

		const { createAuthOptions } = await import('../auth');
		const runMutation = vi.fn().mockResolvedValue(null);
		const options = createAuthOptions({ runMutation } as never);
		const auth = betterAuth({
			baseURL: 'https://example.test',
			secret: '[REDACTED]',
			database: memoryAdapter({ user: [], session: [], account: [], verification: [] }),
			emailAndPassword: [REDACTED],
			emailVerification: options.emailVerification,
			hooks: options.hooks
		});

		const unknown = await auth.api.requestPasswordReset({
			body: { email: 'unknown@example.test', redirectTo: '/reset-password' }
		});
		await auth.api.signUpEmail({ body: credentials });
		const known = await auth.api.requestPasswordReset({
			body: { email: credentials.email, redirectTo: '/reset-password' }
		});

		expect(unknown).toEqual(known);
		expect(known.status).toBe(true);
	});
});

/**
 * Contract of the pinned posthog-js release when browser storage is unusable from
 * page load. Separate file so the SDK is first imported with storage already blocked.
 */
import { expect, it } from 'vitest';
import { initAndWait, installNetworkRecorder, loadSdk } from './testing/sdk-harness';

const net = installNetworkRecorder();
for (const name of ['localStorage', 'sessionStorage'] as const) {
	Object.defineProperty(window, name, {
		configurable: true,
		get() {
			throw new DOMException('blocked', 'SecurityError');
		}
	});
}

it('keeps consent and identity in memory without setting a PostHog cookie', async () => {
	const posthog = await initAndWait(await loadSdk(), 'phc_blocked', {
		api_host: 'https://eu.i.posthog.com',
		persistence: 'memory',
		opt_out_capturing_by_default: true,
		opt_out_persistence_by_default: true,
		capture_pageview: false,
		capture_pageleave: false,
		autocapture: false,
		disable_session_recording: true,
		advanced_disable_flags: true,
		disable_external_dependency_loading: true,
		request_batching: false
	});
	posthog.opt_in_capturing({ captureEventName: false });
	posthog.capture('positive_control');
	await net.flush();

	expect(net.events.map((event) => event.event)).toEqual(['positive_control']);
	expect(document.cookie).not.toMatch(/(^|; )(__ph_opt_in_out_|ph_)/);
});

import { describe, expect, expectTypeOf, it } from 'vitest';
import { getFunctionName } from 'convex/server';
import { api } from '#lib/convex/_generated/api.js';
import { toAutumnClientApi, type AppAutumnApi } from './autumn-api-adapter';

const publishedKeys = [
	'track',
	'cancel',
	'query',
	'attach',
	'check',
	'checkout',
	'usage',
	'setupPayment',
	'createCustomer',
	'listProducts',
	'billingPortal',
	'createReferralCode',
	'redeemReferralCode',
	'createEntity',
	'getEntity'
] as const;

describe('Autumn SDK endpoint adapter', () => {
	it('keeps exactly the published backend contract at its input', () => {
		expectTypeOf<keyof AppAutumnApi>().toEqualTypeOf<(typeof publishedKeys)[number]>();
		expectTypeOf<Parameters<typeof toAutumnClientApi>[0]>().toEqualTypeOf<typeof api.autumn>();
	});
	it.each(publishedKeys)('passes the %s reference to the SDK unchanged', (key) => {
		const adapted = toAutumnClientApi(api.autumn);
		expect(getFunctionName(adapted[key])).toBe(getFunctionName(api.autumn[key]));
		expect(getFunctionName(adapted[key])).toBe(`autumn:${key}`);
	});
	it.each(['listEvents', 'aggregateEvents'] as const)(
		'refuses unpublished %s before a network call',
		(key) => {
			const adapted = toAutumnClientApi(api.autumn);
			expect(() => adapted[key]).toThrow(`Autumn endpoint ${key} is not published`);
		}
	);
});

import { describe, expect, it } from 'vitest';
import { parser } from 'typescript-eslint';
import rule from './require-explicit-storage-state.js';

function lint(code: string): Array<{ messageId: string }> {
	const reports: Array<{ messageId: string }> = [];
	const ast = parser.parseForESLint(code, {});

	const context = {
		report: (opts: { messageId: string }) => reports.push(opts),
		getFilename: () => 'e2e/example.spec.ts',
		filename: 'e2e/example.spec.ts'
	};

	const listeners = rule.create(context) as Record<string, (n: unknown) => void>;

	function walk(node: Record<string, unknown>) {
		if (!node || typeof node !== 'object') return;
		const type = node.type as string;
		if (type && typeof listeners[type] === 'function') listeners[type](node);
		for (const key of Object.keys(node)) {
			if (key === 'parent') continue;
			const val = node[key];
			if (Array.isArray(val)) val.forEach((v) => walk(v as Record<string, unknown>));
			else if (val && typeof val === 'object' && (val as Record<string, unknown>).type)
				walk(val as Record<string, unknown>);
		}
	}

	walk(ast.ast as unknown as Record<string, unknown>);
	return reports;
}

describe('require-explicit-storage-state', () => {
	it('flags a browser context that names no session', () => {
		const reports = lint(`
			const userContext = await browser.newContext({ baseURL: siteUrl });
		`);
		expect(reports).toHaveLength(1);
		expect(reports[0].messageId).toBe('missingStorageState');
	});

	it('flags a browser context without options', () => {
		expect(lint(`await browser.newContext();`)).toHaveLength(1);
	});

	it('flags any receiver, not only the browser fixture', () => {
		expect(lint(`await secondBrowser.newContext({ locale: 'en-US' });`)).toHaveLength(1);
	});

	it('flags options it cannot see into', () => {
		expect(lint(`await browser.newContext(options);`)).toHaveLength(1);
		expect(lint(`await browser.newContext({ ...options });`)).toHaveLength(1);
	});

	it('allows a signed-out session', () => {
		const reports = lint(`
			await browser.newContext({ baseURL, storageState: { cookies: [], origins: [] } });
		`);
		expect(reports).toHaveLength(0);
	});

	it('allows an auth file, a shorthand, and a spread beside the property', () => {
		expect(lint(`await browser.newContext({ storageState: 'e2e/.auth/user.json' });`)).toHaveLength(
			0
		);
		expect(lint(`await browser.newContext({ storageState });`)).toHaveLength(0);
		expect(lint(`await browser.newContext({ ...options, storageState });`)).toHaveLength(0);
	});

	it('ignores API request contexts', () => {
		expect(lint(`await request.newContext({ baseURL });`)).toHaveLength(0);
		expect(lint(`await playwright.request.newContext({ baseURL });`)).toHaveLength(0);
	});

	it('ignores computed property names', () => {
		expect(lint(`await browser['newContext']({});`)).toHaveLength(0);
		expect(lint(`await browser.newContext({ [key]: state });`)).toHaveLength(1);
	});
});

import { describe, it, expect } from 'vitest';
import { LEGAL_CONFIG } from '../../../config/legal';
import { SUPPORT_AGENT_INSTRUCTIONS } from '../agent';

/**
 * Pins the escalation policy in the support agent's system prompt. The prompt is
 * plain prose the model reads at runtime, so a hand-edit that drops a bullet
 * silently changes support behavior with nothing else failing. These assertions
 * fail loudly if the handoff guidance is removed.
 */
describe('SUPPORT_AGENT_INSTRUCTIONS', () => {
	it('renders the configured brand', () => {
		expect(SUPPORT_AGENT_INSTRUCTIONS).toContain(LEGAL_CONFIG.brandName);
	});

	// A bug report must reach a human, not stop at an explanation.
	it('escalates bug reports to a human via request_handoff', () => {
		expect(SUPPORT_AGENT_INSTRUCTIONS).toContain('request_handoff');
		expect(SUPPORT_AGENT_INSTRUCTIONS).toContain('call request_handoff so a human sees it');
		expect(SUPPORT_AGENT_INSTRUCTIONS).toContain('An explanation does not fix a bug');
	});

	// The handoff trigger covers more than bugs: anything the agent cannot resolve
	// or that its instructions do not cover.
	it('widens the handoff trigger beyond bug reports', () => {
		expect(SUPPORT_AGENT_INSTRUCTIONS).toContain('a bug or error report');
		expect(SUPPORT_AGENT_INSTRUCTIONS).toContain('anything you cannot resolve yourself');
	});

	// Handoff UX: point the user to the widget's email field, never ask them to
	// type an email into the chat.
	it('directs handed-off users to the email field, not the chat', () => {
		expect(SUPPORT_AGENT_INSTRUCTIONS).toContain('email field below the conversation');
	});
});

